import type { MetadataRoute } from "next";
import { BRAND } from "@/lib/brand";

/** Web app manifest: install name, brand colours and icons (generated by tools/brand). */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: BRAND.name,
    short_name: "Remote AI",
    description: "Remote jobs, freelance work, hiring and projects in one place.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: BRAND.mist,
    theme_color: BRAND.blue,
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icons/maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
